# >>> CHOICES
_choice_deny() {
    printf '%s\t%s\n' \
        warnings 'any warning' \
        unmaintained 'unmaintained crate' \
        unsound 'unsound crate' \
        yanked 'yanked crate version'
}

_choice_ignore() {
    local db="${argc_db:-$HOME/.cargo/advisory-db}"
    [[ $db == '~'* ]] && db="$HOME${db:1}"
    [[ -d $db ]] || return 0
    find "$db/crates" "$db/rust" -name 'RUSTSEC-*.md' 2>/dev/null | sed 's#.*/##; s#\.md$##'
}

_choice_target_arch() {
    printf '%s\n' x86_64 x86 aarch64 arm arm64ec mips mips64 powerpc powerpc64 riscv32 riscv64 s390x sparc sparc64 wasm32 wasm64 loongarch64 amdgpu avr bpf csky hexagon loongarch32 m68k mips32r6 mips64r6 msp430 nvptx64 xtensa
}

_choice_target_os() {
    printf '%s\n' linux windows macos ios android freebsd netbsd openbsd dragonfly solaris illumos fuchsia redox haiku hermit emscripten wasi uefi none aix amdhsa cuda cygwin espidf helenos horizon hurd l4re lynxos178 managarm motor nto nuttx psp psx qnx qurt rtems solid_asp3 teeos trusty tvos unknown vexos visionos vita vxworks watchos xous zkvm
